import{_ as i,o as a,c as e,a3 as r}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"四书五经","description":"儒家经典的总入口：四书（大学、中庸、论语、孟子）与五经（诗、书、礼、易、春秋）的导读与阅读次序。","frontmatter":{"title":"四书五经","description":"儒家经典的总入口：四书（大学、中庸、论语、孟子）与五经（诗、书、礼、易、春秋）的导读与阅读次序。","category":"landing","aliases":["四书五经","四书","五经","sishu wujing","儒家经典"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/index.md","filePath":"lizhimingde/sishu-wujing/index.md","lastUpdated":1789987057000}'),d={name:"lizhimingde/sishu-wujing/index.md"};function n(l,t,h,s,g,o){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="四书五经" tabindex="-1">四书五经 <a class="header-anchor" href="#四书五经" aria-label="Permalink to &quot;四书五经&quot;">​</a></h1><p>中国传统士人读书的骨干书目。<strong>四书</strong>是南宋朱熹编定的四部入门典籍，<strong>五经</strong>是汉代以来确立的五部经典。先立骨架、再逐篇补原文与解读——这里先是入口，不是全书。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p><strong>四书</strong>： <a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></p><p><strong>五经</strong>： <a href="/Dao/lizhimingde/sishu-wujing/shijing/">诗经</a> · <a href="/Dao/lizhimingde/sishu-wujing/shangshu/">尚书</a> · <a href="/Dao/lizhimingde/sishu-wujing/liji/">礼记</a> · <a href="/Dao/lizhimingde/sishu-wujing/yijing">周易</a> · <a href="/Dao/lizhimingde/sishu-wujing/chunqiu/">春秋</a></p><ul><li>四书原非一书：朱子从《礼记》中抽出《大学》《中庸》，与《论语》《孟子》合编并作注，成为后世科举与蒙学的主干教材。</li><li>五经之名始于汉：诗、书、礼、易、春秋。其中「礼」后世多取《礼记》（另有《仪礼》《周礼》，合称三礼）；「春秋」通常与《左传》合读。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>它是「修身—从政—治学」的共同语汇</strong>：后世两千年的文章、典故、成语，大半从这里长出来。</li><li><strong>四书管心性与日用，五经管政治、历史与文教</strong>：一内一外，互相补足。</li><li><strong>与本仓其他部分互为参照</strong>：四书五经讲入世与修德，「道枢典藏」讲道家原典——两条脉络并置，读者才能看清中国思想的完整地形。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><p>传统的次序是<strong>先四书、后五经</strong>；朱子的建议是先《大学》立纲领，再《论语》知日用，再《孟子》见思辨，然后《中庸》究心性。</p><ol><li><strong>《大学》</strong> —— 三纲八目，先看清儒家为学与为政的整个框架；</li><li><strong>《论语》</strong> —— 二十篇语录，看孔子与其弟子在日用中的问答；</li><li><strong>《孟子》</strong> —— 十四篇论辩，看性与天、王与霸的思想张力；</li><li><strong>《中庸》</strong> —— 三十三章，看心性与天道的精微处；</li><li><strong>五经</strong> —— 按兴趣与需要分流：读文学从《诗经》，读政治史从《尚书》《春秋》，读礼制从《礼记》，读源理回《周易》。</li></ol><blockquote><p>不必一次读完，也不必按顺序从头到尾。<strong>先把目录感立起来</strong>，再照兴趣进入。</p></blockquote><h2 id="四书" tabindex="-1">四书 <a class="header-anchor" href="#四书" aria-label="Permalink to &quot;四书&quot;">​</a></h2><table tabindex="0"><thead><tr><th>经典</th><th style="text-align:right;">篇数</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a></td><td style="text-align:right;">经 1 + 传 10</td><td>三纲领八条目，儒家为学为政的总框架</td></tr><tr><td><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a></td><td style="text-align:right;">33 章</td><td>天命之谓性、致中和，心性与天道的精微处</td></tr><tr><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a></td><td style="text-align:right;">20 篇</td><td>孔子与弟子的语录问答，日用之中的德与学</td></tr><tr><td><a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></td><td style="text-align:right;">14 篇（7 篇各分上下）</td><td>性善、仁政、浩然之气，论辩中的思想张力</td></tr></tbody></table><h2 id="五经" tabindex="-1">五经 <a class="header-anchor" href="#五经" aria-label="Permalink to &quot;五经&quot;">​</a></h2><table tabindex="0"><thead><tr><th>经典</th><th style="text-align:right;">篇数</th><th>一句话</th></tr></thead><tbody><tr><td><a href="/Dao/lizhimingde/sishu-wujing/shijing/">诗经</a></td><td style="text-align:right;">305 篇（风雅颂三体）</td><td>中国最早的诗歌总集，也是「兴观群怨」的教化之源</td></tr><tr><td><a href="/Dao/lizhimingde/sishu-wujing/shangshu/">尚书</a></td><td style="text-align:right;">58 篇</td><td>上古政教文告汇编，读中国政治观念的源头</td></tr><tr><td><a href="/Dao/lizhimingde/sishu-wujing/liji/">礼记</a></td><td style="text-align:right;">49 篇</td><td>礼制的义理与生活细节，《大学》《中庸》即出其中</td></tr><tr><td><a href="/Dao/lizhimingde/sishu-wujing/yijing">周易</a></td><td style="text-align:right;">64 卦</td><td>群经之首。本站已有完整板块，从此处进入</td></tr><tr><td><a href="/Dao/lizhimingde/sishu-wujing/chunqiu/">春秋</a></td><td style="text-align:right;">12 公编年</td><td>与《左传》合读，春秋笔法与史事并见</td></tr></tbody></table><h2 id="当前进度" tabindex="-1">当前进度 <a class="header-anchor" href="#当前进度" aria-label="Permalink to &quot;当前进度&quot;">​</a></h2><ul><li><p>九部经典的总览页<strong>一页到位</strong>：是什么 / 为什么重要 / 怎么读 / <strong>篇章全索引</strong>（篇名与路径）</p></li><li><p><strong>章节页骨架已全部建成，一章一页、目录与文件一一对应</strong>（与《道德经》同一整理方式）：</p><table tabindex="0"><thead><tr><th>经典</th><th style="text-align:right;">章节页</th><th>粒度</th></tr></thead><tbody><tr><td>大学</td><td style="text-align:right;">1</td><td><strong>全篇一页</strong>（经 1 + 传 10，页内十一节）✅ 原文已录入</td></tr><tr><td>中庸</td><td style="text-align:right;">33</td><td>三十三章</td></tr><tr><td>论语</td><td style="text-align:right;">20</td><td>二十篇</td></tr><tr><td>孟子</td><td style="text-align:right;">14</td><td>七篇各分上下</td></tr><tr><td>诗经</td><td style="text-align:right;">305</td><td>逐篇（风/雅/颂）</td></tr><tr><td>尚书</td><td style="text-align:right;">58</td><td>逐篇（虞/夏/商/周书）</td></tr><tr><td>礼记</td><td style="text-align:right;">49</td><td>逐篇</td></tr><tr><td>春秋</td><td style="text-align:right;">12</td><td>十二公</td></tr><tr><td><strong>合计</strong></td><td style="text-align:right;"><strong>492</strong></td><td>——</td></tr></tbody></table></li><li><p><strong>大学已完成原文录入</strong>（全篇一页、竹简 / 经典两种读法、经典模式下生词可点、含三问解读与现代重述），作为其余各部的样板</p></li><li><p>其余各章的<strong>原文转录、字词释义与逐章解读</strong>分批推进（底本到位后逐篇补）</p></li><li><p>《周易》不重复建——正文阅读请往<a href="/Dao/yijing/">易经板块</a></p></li></ul><h2 id="底本与做法" tabindex="-1">底本与做法 <a class="header-anchor" href="#底本与做法" aria-label="Permalink to &quot;底本与做法&quot;">​</a></h2><ul><li>原文以通行本为准；异文、版本差异会在篇页中标注，不擅改底本。</li><li>注释与导读分两层：<strong>原典层</strong>（原文、字词）与<strong>解读层</strong>（象/理/用、现代重述、我的理解）。</li><li>未整理的篇页统一标注「待整理」，先让目录与路径立住，再逐篇补内容。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/">立志明德</a>——本栏目总入口</li><li><a href="/Dao/lizhimingde/liaofan-sixun/">了凡四训</a>、<a href="/Dao/lizhimingde/qianziwen/">千字文</a>——同栏目下的修身劝善与蒙学典籍</li><li><a href="/Dao/yijing/">易经板块</a>——五经之「易」的正文所在</li></ul>',22)])])}const x=i(d,[["render",n]]);export{m as __pageData,x as default};
